<script setup lang="ts">
import axios from 'axios'
import { computed, onMounted, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { renderAsync } from 'docx-preview'
import InspectionQuery from './InspectionQuery.vue'
import InspectionFlow from './InspectionFlow.vue'
import '../../styles/radiology-ppt-entry.css'
import { allLibraryPages, doseDraftKey } from './personalDoseSupport'

const props=defineProps<{token:string;username:string;openCaseId?:number;openEdit?:boolean;canReview:boolean;canApprove:boolean;canGenerateReport:boolean}>()
const emit=defineEmits<{ 'open-inspection':[{id:number;modality:'CT'|'DR'|'DOSE';edit?:boolean}] }>()
const queryVisible=ref(false), archiveRows=ref<any[]>([])
async function queryOpen(row:{id:number;modality:'CT'|'DR'|'DOSE';edit?:boolean}){if(dirty.value){try{await ElMessageBox.confirm('当前修改未提交，草稿已保存在本机，是否切换？','切换项目')}catch{return}}queryVisible.value=false;if(row.modality==='DOSE')await open(row.id,!!row.edit);else emit('open-inspection',row)}
async function loadReports(){archiveRows.value=form.value.id?(await api.get(`/api/personal-dose/cases/${form.value.id}/reports`)).data:[]}
const api=axios.create({baseURL:import.meta.env.VITE_API_BASE_URL || '/'})
api.interceptors.request.use(c=>{c.headers.Authorization=`Bearer ${props.token}`;return c})
type Person={dosimeterNo:string;name:string;sex:string;occupationCategory:string;job:string;startDate:string;endDate:string;wearingPosition:string;wearingDays?:number}
type Reading={sampleType:string;dosimeterNo:string;name:string;values:string[];cf:string}
type Project={id?:number;version?:number;status?:string;personnel:Person[];readings:Reading[];[key:string]:any}
const blank=():Project=>({receipt:'',unitName:'',unitAddress:'',submittingUnit:'',commissioningUnit:'',detectionCategory:'委托检测',location:'',city:'',county:'',sampleName:'个人剂量计',sampleCount:'',packaging:'剂量计盒',sampleCondition:'正常',monitoringMonths:'3',monitoringItem:'X、γ射线个人剂量当量',monitoredQuantity:'Hp(10)',cycle:'',monitoringStart:'',monitoringEnd:'',distributionStart:'',distributionEnd:'',receivedDate:'',inspectionDate:'',reportDate:'',standardBasis:'GBZ 128—2019 职业性外照射个人监测规范',detector:'',detectorType:'',instrumentDescription:'',mdl:'',investigationLevel:'',conclusion:'',personnel:[],readings:[]})
const statusNames:Record<string,string>={DRAFT:'草稿',DATA_ENTERED:'已录入',CALCULATED:'已计算',PENDING_REVIEW:'待复核',REVIEWED:'待签发',APPROVED:'已签发',REPORTED:'已出报告'}
const cases=ref<Project[]>([]), total=ref(0), page=ref(1), keyword=ref(''), status=ref(''), busy=ref(false)
const viewStage=ref(1),editBase=ref(false),selectedPeople=ref<Person[]>([]),selectedReadings=ref<Reading[]>([])
function goStage(n:number){viewStage.value=n;if(n<=2)tab.value='base';else if(n===3)tab.value='evaluation';else tab.value='report'}
function rangeValue(key:string):[string,string]{return [form.value[key+'Start']||'',form.value[key+'End']||'']}
function setRange(key:string,v:string[]|null){form.value[key+'Start']=v?.[0]||'';form.value[key+'End']=v?.[1]||''}
function removeSelectedPeople(){form.value.personnel=form.value.personnel.filter(p=>!selectedPeople.value.includes(p));selectedPeople.value=[]}
function removeSelectedReadings(){form.value.readings=form.value.readings.filter(r=>!selectedReadings.value.includes(r));selectedReadings.value=[]}
const selected=ref<Project>(), form=ref<Project>(blank()), tab=ref('base'), wizard=ref(false), step=ref(0), dirty=ref(false), applying=ref(false)
const standards=ref<any[]>([]), devices=ref<any[]>([]), standardIds=ref<number[]>([]), deviceId=ref<number>()
const editable=computed(()=>!selected.value || ['DRAFT','DATA_ENTERED','CALCULATED'].includes(selected.value.status || 'DRAFT'))
const stage=computed(()=>({DRAFT:0,DATA_ENTERED:1,CALCULATED:2,PENDING_REVIEW:3,REVIEWED:3,APPROVED:4,REPORTED:4}[selected.value?.status || 'DRAFT'] || 0))
const draftKey=computed(()=>doseDraftKey(props.username,form.value.id))
const draftError=ref(false)
async function confirmLeave(){if(!dirty.value)return true;try{await ElMessageBox.confirm('当前修改尚未提交，草稿已保存在本机。是否切换模块？','未保存的内容');return true}catch{return false}}
defineExpose({confirmLeave})
function storeDraft(notify=false){try{localStorage.setItem(draftKey.value,JSON.stringify(form.value));draftError.value=false;if(notify)ElMessage.success('草稿已保存到本机，重新登录后可继续填写')}catch{draftError.value=true;if(notify)ElMessage.error('本机存储不可用，请保持页面打开并保存项目')}}
function readDraft(){const legacy=`personal-dose-draft:${props.token.slice(-16)}:${form.value.id || 'new'}`;const saved=localStorage.getItem(draftKey.value)||sessionStorage.getItem(legacy);if(saved&&!localStorage.getItem(draftKey.value)){localStorage.setItem(draftKey.value,saved);sessionStorage.removeItem(legacy)}return saved}
watch(form,()=>{if(!applying.value && editable.value){dirty.value=true;storeDraft()}},{deep:true,flush:'sync'})
function assign(d:Project){applying.value=true;form.value=JSON.parse(JSON.stringify(d));selected.value=d.id?JSON.parse(JSON.stringify(d)):undefined;dirty.value=false;applying.value=false}
async function run(fn:()=>Promise<void>){busy.value=true;try{await fn()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.message || e.message || '操作失败')}finally{busy.value=false}}
async function load(){const r=await api.get('/api/personal-dose/cases',{params:{keyword:keyword.value,status:status.value,page:page.value-1,size:20}});cases.value=r.data.content;total.value=r.data.totalElements}
async function open(id:number,edit=false){await run(async()=>{if(dirty.value)await ElMessageBox.confirm('当前编辑未保存，是否切换项目？','未保存的内容');assign((await api.get(`/api/personal-dose/cases/${id}`)).data);tab.value='base';viewStage.value=stage.value+1;editBase.value=edit&&editable.value;if(edit){viewStage.value=2;tab.value='base'}await loadReports();const saved=readDraft();if(saved && editable.value){const draft=JSON.parse(saved);if(draft.version===form.value.version){try{await ElMessageBox.confirm('发现本项目未提交的本地草稿，是否恢复？','恢复草稿');form.value=draft}catch{localStorage.removeItem(draftKey.value)}}}})}
async function create(){await run(async()=>{if(dirty.value)await ElMessageBox.confirm('当前编辑未保存，是否新建项目？','未保存的内容');assign(blank());tab.value="base";step.value=0;wizard.value=true;const saved=readDraft();if(saved){try{await ElMessageBox.confirm('发现未完成的新项目草稿，是否恢复？','恢复草稿');form.value=JSON.parse(saved)}catch{localStorage.removeItem(draftKey.value)}}})}
async function persist(){const key=draftKey.value;const d=(await (form.value.id?api.put(`/api/personal-dose/cases/${form.value.id}`,form.value):api.post('/api/personal-dose/cases',form.value))).data;assign(d);localStorage.removeItem(key);await load()}
async function save(){await run(async()=>{await persist();if(wizard.value){tab.value="personnel";viewStage.value=2;}wizard.value=false;editBase.value=false;ElMessage.success('已保存；数据修改后请重新计算')})}
function next(){if(step.value===0 && (!form.value.receipt.trim()||!form.value.unitName.trim()||!form.value.detectionCategory.trim())){ElMessage.warning('请填写受理编号、检测类别和受检单位');return}if(step.value===1&&!form.value.sampleName.trim()){ElMessage.warning('请填写样品名称');return}step.value++}
async function action(name:string,providedComment?:string){await run(async()=>{if(name==='calculate' && dirty.value)await persist();else if(dirty.value)throw new Error('请先保存修改并重新计算');let comment=providedComment ?? '';if(providedComment===undefined && ['submit','review','approve'].includes(name))comment=(await ElMessageBox.prompt('请输入意见（可留空）',({submit:'提交复核',review:'复核通过',approve:'批准报告'} as Record<string,string>)[name],{inputType:'textarea'})).value; if(name==='return')comment=(await ElMessageBox.prompt('请输入退回原因','退回修改',{inputValidator:v=>!!v.trim()||'退回原因不能为空'})).value;else if(['approve','archive'].includes(name))await ElMessageBox.confirm(name==='approve'?'批准后数据将冻结，修改需建立修订版。':'将按批准快照生成归档报告，下载后线下手签盖章。','确认操作');assign((await api.post(`/api/personal-dose/cases/${form.value.id}/actions/${name}`,{version:form.value.version,comment})).data);if(providedComment!==undefined){previewVisible.value=false;previewComplete.value=false;previewComment.value=''}await load();await loadReports();if(name==='calculate'){tab.value='evaluation';viewStage.value=3}else if(['submit','review','return'].includes(name))viewStage.value=4;else if(['approve','archive'].includes(name))viewStage.value=5;ElMessage.success('操作完成')})}
async function revision(){await run(async()=>{assign((await api.post(`/api/personal-dose/cases/${form.value.id}/revision`,{version:form.value.version})).data);tab.value='base';viewStage.value=2;await load();await loadReports()})}
async function remove(){await run(async()=>{await ElMessageBox.confirm('删除此未批准项目？','删除项目');await api.delete(`/api/personal-dose/cases/${form.value.id}`,{params:{version:form.value.version}});localStorage.removeItem(draftKey.value);assign(blank());await load()})}
function addPerson(){form.value.personnel.push({dosimeterNo:'',name:'',sex:'',occupationCategory:'',job:'',startDate:form.value.monitoringStart,endDate:form.value.monitoringEnd,wearingPosition:''})}
function addReading(){form.value.readings.push({sampleType:'TEST',dosimeterNo:'',name:'',values:['','',''],cf:''})}
function match(r:Reading){if(r.sampleType==='TEST'){const p=form.value.personnel.find(p=>p.dosimeterNo===r.dosimeterNo);if(p)r.name=p.name}}
function result(no:string){return form.value.calculation?.rows?.find((r:any)=>r.dosimeterNo===no)}
function days(p:Person){if(!p.startDate||!p.endDate)return '';return Math.round((Date.parse(p.endDate)-Date.parse(p.startDate))/86400000)+1}
function importStandards(){const chosen=standards.value.filter(s=>standardIds.value.includes(s.id));if(chosen.length)form.value.standardBasis=chosen.map(s=>`${s.standardCode} ${s.standardName}`).join('；')}
function importDevice(){const d=devices.value.find(d=>d.id===deviceId.value);if(d)form.value.instrumentDescription+=(form.value.instrumentDescription?'\n':'')+`${d.deviceName}（型号：${d.deviceModel || '—'}；仪器编号：${d.deviceNo || '—'}）[证书编号：${d.certificateNo || '—'}]（有效期：${d.calibrationDate || '—'} 至 ${d.calibrationExpiry || '—'}）`}
const importKind=ref('cases'), importVisible=ref(false), importFile=ref<File>(), importResult=ref<any>(), importVersion=ref<number>()
function showImport(kind:string){if(dirty.value && kind!=='cases'){ElMessage.warning('请先保存当前修改，再导入');return}importKind.value=kind;importVisible.value=true;importFile.value=undefined;importResult.value=undefined;importVersion.value=form.value.version}
function chooseFile(e:Event){importFile.value=(e.target as HTMLInputElement).files?.[0];importResult.value=undefined}
async function upload(dryRun:boolean){await run(async()=>{if(!importFile.value)throw new Error('请选择xlsx文件');const data=new FormData();data.append('file',importFile.value);importResult.value=(await api.post(`/api/personal-dose/import/${importKind.value}`,data,{params:{dryRun,id:importKind.value==='cases'?undefined:form.value.id,version:importVersion.value}})).data;if(!dryRun){if(importResult.value.project)assign(importResult.value.project);await load();importVisible.value=false;ElMessage.success(`已导入 ${importResult.value.count} 条记录`)}})}
async function download(path:string,name:string){await run(async()=>{const r=await api.get(path,{responseType:'blob'});const u=URL.createObjectURL(r.data),a=document.createElement('a');a.href=u;const disposition=r.headers['content-disposition'] as string|undefined;const encoded=disposition?.match(/filename\*=UTF-8''([^;]+)/i);a.download=encoded?decodeURIComponent(encoded[1]!):name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)})}
const previewSection=ref('cover'),previewComplete=ref(false),previewComment=ref('')
const previewVisible=ref(false), previewPages=ref<string[]>([]), previewHost=ref<HTMLElement>(), previewError=ref('')
async function preview(){await run(async()=>{if(dirty.value)throw new Error('请先保存后预览');previewPages.value=[];previewError.value='';previewSection.value='cover';previewComplete.value=false;previewComment.value='';previewVisible.value=true;try{previewPages.value=(await api.get(`/api/personal-dose/cases/${form.value.id}/preview-pages`)).data}catch{const r=await api.get(`/api/personal-dose/cases/${form.value.id}/report`,{params:{preview:true},responseType:'blob'});previewError.value='当前环境不支持服务器分页，以下为Word内容预览；正式分页以下载文件为准。';if(previewHost.value)await renderAsync(r.data,previewHost.value)}})}
async function library(path:string,params:Record<string,any>={}){return allLibraryPages<any>(async page=>(await api.get(path,{params:{...params,page,size:100}})).data)}
async function loadLibraries(){const results=await Promise.allSettled([library('/api/ohdp/basic/standards'),library('/api/ohdp/devices',{status:'NORMAL'})]);if(results[0].status==='fulfilled')standards.value=results[0].value;else ElMessage.warning('检测标准库加载失败，请刷新重试');if(results[1].status==='fulfilled')devices.value=results[1].value;else ElMessage.warning('检测设备库加载失败，请刷新重试')}
async function refresh(){await Promise.all([load(),loadLibraries()])}
onMounted(()=>run(async()=>{await refresh();if(props.openCaseId)await open(props.openCaseId,!!props.openEdit)}))
watch(()=>props.openCaseId,id=>{if(id)void open(id,!!props.openEdit)})

const fieldGroups=[[
 ['receipt','受理编号','text'],['detectionCategory','检测类别','text'],['unitName','受检单位名称','text'],['unitAddress','受检单位地址','text'],['submittingUnit','送检单位','text'],['commissioningUnit','委托单位','text'],['location','检测地点','text'],['city','所在地市','text'],['county','所在县区','text']
],[['sampleName','受检样品名称','text'],['packaging','样品包装','text'],['sampleCount','样品数量','text'],['monitoringMonths','监测周期（月）','text'],['monitoringItem','监测项目','text'],['monitoredQuantity','监测的量','text'],['cycle','第几周期','text'],['sampleCondition','样品性状','text'],['receivedDate','收检日期','date']],
 [['distributionStart','剂量计发放开始日期','date'],['distributionEnd','剂量计发放结束日期','date'],['monitoringStart','监测开始日期','date'],['monitoringEnd','监测结束日期','date'],['inspectionDate','检测日期','date'],['reportDate','报告日期','date'],['detector','检测人','text'],['detectorType','探测器类型','text'],['mdl','最低可探测水平MDL（mSv）','text'],['investigationLevel','本周期调查水平（mSv）','text']]] as const
const wizardFields=[[
 ['receipt','受理编号','text'],['detectionCategory','检测类别','text'],['commissioningUnit','委托单位','text'],['unitName','受检单位名称','text'],['unitAddress','受检单位地址','text'],['location','检测地点','text']
],[['sampleName','受检样品名称','text'],['packaging','样品包装','text'],['sampleCount','样品数量','text'],['monitoringMonths','监测周期（月）','text'],['monitoringItem','监测项目','text'],['monitoredQuantity','监测的量','text']],
 [['distribution','剂量计发放起止日期','range'],['inspectionDate','检测日期','date']]] as const
const summaryFields=[['receipt','受理编号'],['detectionCategory','检测类别'],['inspectionDate','检测日期'],['unitName','受检单位名称'],['location','检测地点'],['monitoringMonths','监测周期（月）'],['sampleName','受检样品名称'],['sampleCount','样品数量'],['mdl','MDL（mSv）']] as const
const supplementalFields=computed(()=>fieldGroups.flat().filter(([key])=>!wizardFields.flat().some(([k])=>k===key)&&!['distributionStart','distributionEnd','detector'].includes(key)))
</script>

<template>
<div class="dose-workbench" v-loading="busy">
<header class="dose-heading"><h2>个人剂量监测<span v-if="selected">--{{form.receipt}}</span></h2><div><el-button @click="run(refresh)">刷新</el-button><el-button @click="download('/api/personal-dose/import-template/cases','个人剂量项目导入模板.xlsx')">模板下载</el-button></div></header>
<InspectionFlow :model-value="viewStage" :selected="!!selected" @update:model-value="goStage" />
<div class="dose-layout" :class="{recording:!!selected && viewStage===2}"><aside class="dose-case-rail"><div class="dose-search"><el-input v-model="keyword" placeholder="受理编号" clearable @keyup.enter="page=1;run(load)"/><el-select v-model="status" clearable placeholder="全部状态"><el-option v-for="(label,key) in statusNames" :key="key" :label="label" :value="key"/></el-select><el-button @click="page=1;run(load)">查询</el-button></div><button v-for="c in cases" :key="c.id" class="dose-case" :class="{active:selected?.id===c.id}" @click="open(c.id!)"><strong>{{c.receipt}}</strong><span>{{c.unitName}}</span><small>{{statusNames[c.status || "DRAFT"]}}</small></button><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="run(load)"/><el-button v-if="selected" @click="create">创建新的项目</el-button></aside>
<main class="dose-main" :class="{'dose-ppt-entry':viewStage===2}"><el-alert v-if="draftError" title="本机草稿保存失败，请保持页面打开并及时保存项目。" type="error" :closable="false"/>
<div v-if="!selected" class="dose-empty"><strong>个人剂量</strong><p>选择左侧案例开始录入<br>或</p><el-button type="primary" @click="create">创建新的项目</el-button><el-button type="primary" @click="showImport('cases')">Excel批量导入</el-button></div>
<template v-else><div class="ppt-page-actions" v-if="viewStage<=2"><el-button v-if="tab==='base'" :disabled="!editable" @click="editBase=!editBase">编辑信息</el-button><el-button :disabled="!editable" @click="save">{{tab==='base'?'保存数据':'保存'}}</el-button><el-button v-if="tab==='readings'" :disabled="!editable" @click="action('calculate')">计算</el-button><el-button v-if="viewStage===1" type="primary" @click="viewStage===1?goStage(2):tab==='base'?tab='personnel':tab==='personnel'?tab='readings':goStage(3)">下一步</el-button></div>
<el-alert v-if="!editable" title="当前数据已锁定。审核中可退回修改；批准后请建立修订版。" type="info" :closable="false"/>
<el-tabs v-if="viewStage<=2" v-model="tab"><el-tab-pane label="基本信息" name="base"><div v-if="editBase"><el-form label-position="top" :disabled="!editable"><div v-for="(group,i) in wizardFields" :key="i"><h4>{{['受检单位','样品信息','检测信息'][i]}}</h4><div class="dose-grid dose-wizard-grid" :class="{'unit-step':i===0}"><el-form-item v-for="[key,label,type] in group" :key="key" :label="label" :required="['receipt','unitName','detectionCategory','sampleName'].includes(key)"><el-date-picker v-if="type==='range'" :model-value="rangeValue(key)" type="daterange" value-format="YYYY-MM-DD" range-separator="至" @update:model-value="(v:any)=>setRange(key,v)"/><el-date-picker v-else-if="type==='date'" v-model="form[key]" value-format="YYYY-MM-DD" type="date"/><el-input v-else v-model="form[key]" :maxlength="key==='unitName'?255:500"/></el-form-item></div></div><div class="dose-library"><el-select v-model="standardIds" multiple filterable placeholder="从标准库选择"><el-option v-for="s in standards" :key="s.id" :value="s.id" :label="s.standardCode+' '+s.standardName"/></el-select><el-button @click="importStandards">导入检测依据</el-button></div><el-form-item label="检测依据"><el-input v-model="form.standardBasis" type="textarea"/></el-form-item><div class="dose-library"><el-select v-model="deviceId" filterable placeholder="从检测设备库选择"><el-option v-for="d in devices" :key="d.id" :value="d.id" :label="d.deviceName+' '+(d.deviceNo||'')"/></el-select><el-button @click="importDevice">导入检测设备及证书</el-button></div><el-form-item label="检测设备及证书（可补充检定、校准证书及有效期）"><el-input v-model="form.instrumentDescription" type="textarea" :rows="3"/></el-form-item><el-form-item label="检测人"><el-input v-model="form.detector"/></el-form-item><details class="ppt-help"><summary>报告及查询补充信息</summary><div class="dose-grid"><el-form-item v-for="[key,label,type] in supplementalFields" :key="key" :label="label"><el-date-picker v-if="type==='date'" v-model="form[key]" type="date" value-format="YYYY-MM-DD"/><el-input v-else v-model="form[key]"/></el-form-item></div></details></el-form></div><el-descriptions v-else border :column="3" class="dose-summary"><el-descriptions-item v-for="[key,label] in summaryFields" :key="key" :label="label">{{form[key]||'—'}}</el-descriptions-item><el-descriptions-item label="检测依据" :span="3">{{form.standardBasis}}</el-descriptions-item><el-descriptions-item label="检测设备及证书" :span="3">{{form.instrumentDescription}}</el-descriptions-item></el-descriptions></el-tab-pane><el-tab-pane label="人员信息" name="personnel"><div class="dose-toolbar"><el-button :disabled="!editable" @click="showImport('personnel')">Excel批量导入</el-button><el-button @click="download('/api/personal-dose/import-template/personnel','个人剂量人员导入模板.xlsx')">模板下载</el-button></div><el-table :data="form.personnel" border @selection-change="(v:Person[])=>selectedPeople=v"><el-table-column type="selection" width="38"/><el-table-column type="index" label="序号" width="55"/><el-table-column v-for="[key,label] in [['dosimeterNo','剂量计编号'],['name','姓名'],['sex','性别'],['occupationCategory','职业类别'],['job','工作岗位']]" :key="key" :label="label" :min-width="key==='sex'?80:125"><template #default="{row}"><el-input v-model="row[key!]" :disabled="!editable"/></template></el-table-column><el-table-column label="佩戴起止日期" width="255"><template #default="{row}"><el-date-picker :model-value="[row.startDate,row.endDate]" type="daterange" value-format="YYYY-MM-DD" range-separator="至" :disabled="!editable" style="width:230px" @update:model-value="(v:any)=>{row.startDate=v?.[0]||'';row.endDate=v?.[1]||''}" /></template></el-table-column><el-table-column label="佩戴天数" class-name="ppt-readonly" width="95"><template #default="{row}">{{days(row)}}</template></el-table-column><el-table-column label="佩戴位置" width="125"><template #default="{row}"><el-input v-model="row.wearingPosition" :disabled="!editable"/></template></el-table-column></el-table><div class="row-actions"><el-button :disabled="!editable" @click="addPerson">增加行</el-button><el-button :disabled="!editable||!selectedPeople.length" @click="removeSelectedPeople">删除行</el-button></div></el-tab-pane><el-tab-pane label="数据录入" name="readings"><div class="dose-toolbar"><el-button :disabled="!editable" @click="showImport('readings')">Excel批量导入</el-button><el-button @click="download('/api/personal-dose/import-template/readings','个人剂量测量导入模板.xlsx')">模板下载</el-button></div><el-table :data="form.readings" border @selection-change="(v:Reading[])=>selectedReadings=v"><el-table-column type="selection" width="38"/><el-table-column label="样品类别" width="160"><template #default="{row}"><el-select v-model="row.sampleType" :disabled="!editable" @change="match(row)"><el-option label="待测剂量计" value="TEST"/><el-option label="本底剂量计" value="BACKGROUND"/><el-option label="质控剂量计" value="QC"/></el-select></template></el-table-column><el-table-column label="剂量计编号" width="150"><template #default="{row}"><el-input v-model="row.dosimeterNo" :disabled="!editable" @change="match(row)"/></template></el-table-column><el-table-column label="姓名" width="110"><template #default="{row}"><el-input v-model="row.name" :disabled="!editable"/></template></el-table-column><el-table-column label="原始测量值" min-width="380"><template #default="{row}"><div class="raw-values"><el-input v-for="(_,i) in row.values" :key="i" v-model="row.values[i]" :disabled="!editable" :aria-label="'原始测量值'+(Number(i)+1)"/><el-button :disabled="!editable||row.values.length<=1" @click="row.values.pop()">−</el-button><el-button :disabled="!editable||row.values.length>=50" @click="row.values.push('')">+</el-button></div></template></el-table-column><el-table-column label="刻度因子Cf" width="120"><template #default="{row}"><el-input v-model="row.cf" :disabled="!editable"/></template></el-table-column><el-table-column label="均值" class-name="ppt-readonly" width="100"><template #default="{row}">{{dirty?'待重算':result(row.dosimeterNo)?.mean || '—'}}</template></el-table-column><el-table-column label="净计数" class-name="ppt-readonly" width="100"><template #default="{row}">{{dirty?'待重算':result(row.dosimeterNo)?.net || '—'}}</template></el-table-column><el-table-column label="Hₚ(10)" class-name="ppt-readonly" width="120"><template #default="{row}">{{dirty?'待重算':result(row.dosimeterNo)?.hp10 || '—'}}</template></el-table-column></el-table><div class="row-actions"><el-button :disabled="!editable" @click="addReading">增加行</el-button><el-button :disabled="!editable||!selectedReadings.length" @click="removeSelectedReadings">删除行</el-button></div><details class="ppt-help"><summary>计算说明</summary><p>原始测量值单位：mSv。待测剂量计编号、姓名须与人员信息一致。净计数＝待测均值－本底均值；Hₚ(10)＝净计数×Cᶠ，保留2位小数。</p></details></el-tab-pane></el-tabs><div v-if="viewStage===2" class="ppt-page-actions ppt-next-actions"><el-button type="primary" @click="tab==='base'?tab='personnel':tab==='personnel'?tab='readings':goStage(3)">下一步</el-button></div>
<section v-if="viewStage===3"><el-descriptions :column="2" border><el-descriptions-item label="受理编号">{{form.receipt}}</el-descriptions-item><el-descriptions-item label="受检单位名称">{{form.unitName}}</el-descriptions-item><el-descriptions-item label="检测标准">{{form.standardBasis}}</el-descriptions-item></el-descriptions><h4>总体评价</h4><el-input v-model="form.conclusion" type="textarea" :rows="5" :disabled="!editable" placeholder="请结合本周期结果填写评价；年度限值评价需全年累计监测资料，系统不会自动判为年度合格。"/><div class="dose-toolbar"><el-button @click="goStage(2)">修改</el-button><el-button :disabled="!editable" @click="save">保存</el-button><el-button type="primary" @click="goStage(4)">下一步</el-button></div></section><section v-if="viewStage>=4"><div v-if="viewStage===4" class="ppt-page-actions"><el-button v-if="selected.status==='CALCULATED'" :disabled="dirty" type="primary" @click="action('submit')">发送</el-button><el-button @click="goStage(3)">返回修改</el-button></div><el-alert title="本期采用线下签章：批准并生成归档报告后，下载Word手签盖章。" type="info" :closable="false"/><div class="dose-toolbar"><el-button v-if="viewStage===4&&selected.status==='PENDING_REVIEW'&&canReview" type="primary" @click="action('review')">复核通过</el-button><el-button v-if="viewStage===4&&selected.status==='REVIEWED'&&canApprove" type="primary" @click="action('approve')">签发</el-button><el-button v-if="(selected.status==='PENDING_REVIEW'&&canReview)||(selected.status==='REVIEWED'&&canApprove)" @click="action('return')">退回修改</el-button><el-button @click="preview">报告预览</el-button><el-button v-if="viewStage===5&&selected.status==='APPROVED'&&canGenerateReport" type="primary" @click="action('archive')">生成检测报告</el-button><el-button v-if="viewStage===5&&selected.status==='REPORTED'&&canGenerateReport" type="primary" @click="download(`/api/personal-dose/cases/${form.id}/report`,`${form.receipt}-个人剂量检测报告.docx`)">下载</el-button><el-button v-if="['APPROVED','REPORTED'].includes(selected.status||'')" @click="revision">建立修订版</el-button><el-button v-if="editable" type="danger" plain @click="remove">删除项目</el-button></div><div v-if="viewStage===5"><h4>报告归档</h4><el-table :data="archiveRows" border><el-table-column prop="reportNo" label="报告编号" min-width="140"/><el-table-column prop="fileName" label="文件名" min-width="300"/><el-table-column prop="generatedBy" label="生成人" width="110"/><el-table-column prop="generatedAt" label="生成时间" width="200"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" :disabled="!canGenerateReport" @click="download(`/api/personal-dose/cases/${row.caseId}/report`,row.fileName)">下载</el-button></template></el-table-column></el-table><p class="dose-note">已归档报告保留原文件；需要变更时建立修订版，各版本可分别下载。</p></div><details><summary>操作记录与文件校验</summary><p v-if="form.reportSha256" class="dose-hash">归档文件SHA-256：{{form.reportSha256}}</p><el-table :data="form.history||[]" border><el-table-column prop="at" label="时间" width="225"/><el-table-column prop="actor" label="操作人" width="125"/><el-table-column label="操作" width="150"><template #default="{row}">{{({calculate:'计算',submit:'提交复核',review:'复核通过',approve:'批准',return:'退回',archive:'报告归档'} as Record<string,string>)[row.action] || row.action}}</template></el-table-column><el-table-column prop="comment" label="说明"/></el-table></details></section></template></main></div>
  <el-dialog v-model="wizard" class="dose-step-dialog" title="新建个人剂量监测案例" width="900px" :close-on-click-modal="false"><el-steps :active="step" align-center><el-step title="受检单位信息"/><el-step title="受检样品信息"/><el-step title="检测机构信息"/><el-step title="确认并创建"/></el-steps><p class="dose-note">填写内容会自动保存在本机</p><el-form label-position="top"><div v-if="step<3" class="dose-grid dose-wizard-grid" :class="{'unit-step':step===0}"><el-form-item v-for="[key,label,type] in wizardFields[step]" :class="{half:['unitName','unitAddress','location'].includes(key)}" :key="key" :label="label" :required="['receipt','unitName','detectionCategory','sampleName'].includes(key)"><el-date-picker v-if="type==='range'" :model-value="rangeValue(key)" type="daterange" value-format="YYYY-MM-DD" range-separator="至" @update:model-value="(v:any)=>setRange(key,v)"/><el-date-picker v-else-if="type==='date'" v-model="form[key]" value-format="YYYY-MM-DD" type="date"/><el-input v-else v-model="form[key]"/></el-form-item></div><template v-if="step===2"><div class="dose-library"><el-select v-model="standardIds" multiple filterable placeholder="从标准库选择"><el-option v-for="s in standards" :key="s.id" :value="s.id" :label="s.standardCode+' '+s.standardName"/></el-select><el-button @click="importStandards">导入依据</el-button></div><el-form-item label="检测依据"><el-input v-model="form.standardBasis" type="textarea"/></el-form-item><div class="dose-library"><el-select v-model="deviceId" filterable placeholder="从设备库选择"><el-option v-for="d in devices" :key="d.id" :value="d.id" :label="d.deviceName+' '+(d.deviceNo||'')"/></el-select><el-button @click="importDevice">导入仪器证书</el-button></div><el-form-item label="检测设备及证书"><el-input v-model="form.instrumentDescription" type="textarea"/></el-form-item><el-form-item label="检测人"><el-input v-model="form.detector"/></el-form-item></template><template v-if="step===3"><el-descriptions border :column="3" class="dose-summary"><el-descriptions-item v-for="[key,label] in summaryFields" :key="key" :label="label"><el-input v-if="key==='mdl'" v-model="form.mdl" aria-label="MDL（mSv）"/><template v-else>{{form[key] || '—'}}</template></el-descriptions-item><el-descriptions-item label="检测依据" :span="3">{{form.standardBasis}}</el-descriptions-item><el-descriptions-item label="检测设备及证书" :span="3">{{form.instrumentDescription || '—'}}</el-descriptions-item></el-descriptions><details><summary>报告及查询补充信息</summary><div class="dose-grid"><el-form-item v-for="[key,label,type] in supplementalFields.filter(f=>f[0]!=='mdl')" :key="key" :label="label"><el-date-picker v-if="type==='date'" v-model="form[key]" type="date" value-format="YYYY-MM-DD"/><el-input v-else v-model="form[key]"/></el-form-item></div></details></template></el-form><template #footer><el-button @click="wizard=false">取消</el-button><el-button @click="storeDraft(true)">保存草稿</el-button><el-button v-if="step>0" @click="step--">上一步</el-button><el-button v-if="step<3" type="primary" @click="next">下一步</el-button><el-button v-else type="primary" :loading="busy" @click="save">确定创建</el-button></template></el-dialog>
  <el-dialog v-model="queryVisible" title="综合查询（CT / DR / 个人剂量）" width="94%" destroy-on-close><InspectionQuery :token="token" @open="queryOpen"/></el-dialog>
  <el-dialog v-model="importVisible" title="Excel批量导入" width="600px"><el-alert :title="importKind==='cases'?'每行创建一个项目；先预检，再确认导入。':'导入将替换此项目对应列表；编号、姓名不匹配时整批拒绝。'" type="warning" :closable="false"/><p><input type="file" accept=".xlsx" @change="chooseFile"/></p><p v-if="importResult">预检通过，共 {{importResult.count}} 条记录。</p><template #footer><el-button @click="upload(true)" :disabled="!importFile" :loading="busy">预检</el-button><el-button type="primary" :disabled="!importResult?.dryRun" :loading="busy" @click="upload(false)">确认导入</el-button></template></el-dialog>
  <el-dialog v-model="previewVisible" title="个人剂量报告预览" width="90%" destroy-on-close><el-alert v-if="previewError" :title="previewError" type="info"/><el-radio-group v-if="previewPages.length" v-model="previewSection"><el-radio-button value="cover">封面</el-radio-button><el-radio-button value="notice">封二</el-radio-button><el-radio-button value="body">正文</el-radio-button></el-radio-group><div class="dose-preview"><img v-for="(src,i) in previewPages" :key="i" v-show="previewSection==='cover'?i===0:previewSection==='notice'?i===1:i>=2" :src="src" :alt="`报告第${i+1}页`"/><div ref="previewHost"/></div><template #footer><el-button @click="previewVisible=false">退出</el-button><el-button @click="previewComplete=true">完成</el-button><template v-if="previewComplete"><el-button v-if="editable" @click="previewVisible=false;goStage(2)">返回修改</el-button><el-button v-if="(selected?.status==='PENDING_REVIEW'&&canReview)||(selected?.status==='REVIEWED'&&canApprove)" @click="action('return')">退回修改</el-button><el-form label-position="top" style="text-align:left"><el-form-item :label="selected?.status==='PENDING_REVIEW'?'复核意见':selected?.status==='REVIEWED'?'签发意见':'编写记录'"><el-input v-model="previewComment" type="textarea" placeholder="可留空"/></el-form-item></el-form><el-button v-if="selected?.status==='CALCULATED'" @click="action('submit',previewComment)">发送</el-button><el-button v-if="selected?.status==='PENDING_REVIEW'&&canReview" @click="action('review',previewComment)">发送</el-button><el-button v-if="selected?.status==='REVIEWED'&&canApprove" @click="action('approve',previewComment)">发送</el-button></template></template></el-dialog>
</div>
